def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: dict representation or None if invalid
    """
    try:
        if value is None:
            return None

        # Handle shapely.geometry.Point or similar objects with x and y attributes
        if hasattr(value, "x") and hasattr(value, "y"):
            return {"x": getattr(value, "x"), "y": getattr(value, "y")}

        # Handle geopy.Point with latitude and longitude
        if hasattr(value, "latitude") and hasattr(value, "longitude"):
            return {"latitude": getattr(value, "latitude"), "longitude": getattr(value, "longitude")}

        # Handle objects with lat and lon attributes
        if hasattr(value, "lat") and hasattr(value, "lon"):
            return {"lat": getattr(value, "lat"), "lon": getattr(value, "lon")}

        # Handle tuples/lists of length 2 (x, y)
        if isinstance(value, (tuple, list)) and len(value) == 2:
            return {"x": value[0], "y": value[1]}

        # Handle dictionary-like objects containing x and y keys
        if isinstance(value, dict):
            if "x" in value and "y" in value:
                return {"x": value["x"], "y": value["y"]}
            if "lat" in value and "lon" in value:
                return {"lat": value["lat"], "lon": value["lon"]}

        # Unrecognized type
        return None
    except Exception:
        # Catch any unexpected errors during dehydration
        return None

