def keys(self):
        """ Return the keys of the record.

        :return: list of key names
        """
        # Determine the underlying record attribute
        record = None
        for attr in ('_record', 'record', '_data', 'data'):
            if hasattr(self, attr):
                record = getattr(self, attr)
                break
        if record is None:
            raise AttributeError("The instance has no record attribute.")
        if not isinstance(record, dict):
            raise TypeError(f"Expected a dict for the record, got {type(record).__name__}.")
        try:
            return list(record.keys())
        except Exception as exc:
            raise RuntimeError(f"Failed to retrieve keys from the record: {exc}") from exc

