def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Assume the record stores its data in an ordered mapping self._data
    # If no internal mapping exists, raise an informative error.
    if not hasattr(self, "_data") or not isinstance(self._data, dict):
        raise AttributeError("The record object does not have a valid '_data' attribute.")

    # If no keys are specified, return all values in order.
    if not keys:
        # Preserve insertion order (dict order in Python 3.7+).
        return list(self._data.values())

    # Prepare a list of keys for index lookup to avoid repeated conversion.
    key_list = list(self._data.keys())
    result = []

    for k in keys:
        # Integer indices are treated as positional indices into the record.
        if isinstance(k, int):
            try:
                # Allow Python's negative indexing semantics.
                key_at_index = key_list[k]
            except IndexError:
                raise IndexError(f"Index {k} is out of range for record keys of length {len(key_list)}.")
            result.append(self._data[key_at_index])
        else:
            # Treat any non-integer as a key into the mapping.
            try:
                result.append(self._data[k])
            except KeyError:
                raise KeyError(f"Key {k!r} not found in the record.")
    return result

