def data(self, *keys):
    """
    Return the record's values as a dictionary keyed by field name.
    If *keys is empty, all fields are included.
    Keys may be integers (indices) or field names.
    If an integer is out of range, raises IndexError.
    If a field name is unknown, the returned value will be None.
    """
    try:
        # Attempt to retrieve the list of all field names in order.
        field_names = list(self.keys())
    except AttributeError:
        raise AttributeError("The object must provide a .keys() method to enumerate fields.")

    # Helper to return all data
    if not keys:
        # Use indexed access or item iteration if present.
        try:
            # Direct iteration over the record gives values in order.
            values_iter = iter(self)
        except TypeError:
            # Fallback to accessing by index if indexing by integer works.
            values_iter = (self[i] for i in range(len(field_names)))
        return dict(zip(field_names, values_iter))

    result = {}
    for key in keys:
        if isinstance(key, int):
            # Index-based lookup
            if key < 0 or key >= len(field_names):
                raise IndexError(f"Index {key} out of bounds for record of length {len(field_names)}")
            name = field_names[key]
            try:
                value = self[key]
            except Exception as exc:
                # In case self[key] fails for an integer but might support integer indexing
                raise IndexError(f"Could not retrieve value at index {key}") from exc
            result[name] = value
        else:
            # Key-based lookup
            if key in field_names:
                try:
                    value = self[key]
                except Exception as exc:
                    # For non-integer indices, fallback to attribute access
                    try:
                        value = getattr(self, key)
                    except AttributeError:
                        value = None  # treat missing attribute as None
                result[key] = value
            else:
                # Unknown key -> None
                result[key] = None
    return result

