def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    if seq is None:
        raise TypeError("seq must not be None")
    try:
        lst = list(seq)
    except Exception as exc:
        raise TypeError("seq must be a sequence") from exc

    for elem in lst:
        if not isinstance(elem, str):
            raise TypeError("all elements in seq must be str")

    n = len(lst)
    a = 1664525
    c = 1013904223
    m = 2**32
    seed = 0
    for i in range(n - 1, 0, -1):
        seed = (a * seed + c) % m
        j = seed % (i + 1)
        lst[i], lst[j] = lst[j], lst[i]
    return lst

