def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Compute cache key
            try:
                k = key(*args, **kwargs) if callable(key) else key
            except Exception as exc:
                raise ValueError("Key function raised an exception") from exc
            # Try to fetch result from cache
            try:
                cached_value = None
                if hasattr(cache, "get"):
                    cached_value = cache.get(k, None)
                else:
                    # Fallback: try dictionary access
                    cached_value = cache[k]
            except Exception:
                cached_value = None
            if cached_value is not None:
                return cached_value
            # Compute result and store in cache
            try:
                result = func(*args, **kwargs)
            except Exception as exc:
                raise exc
            try:
                if lock:
                    with lock:
                        cache[k] = result
                else:
                    cache[k] = result
            except Exception:
                # If cache storage fails, ignore and still return result
                pass
            return result
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper
    return decorator

