    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(func):
        def wrapper(self, *args, **kwargs):
            # Generate cache key using the provided key function
            try:
                cache_key = key(self, *args, **kwargs)
            except Exception as exc:
                raise RuntimeError(f"Key function raised an exception: {exc}") from exc

            # Attempt to retrieve from cache
            try:
                if lock:
                    lock.acquire()
                if cache_key in cache:
                    return cache[cache_key]
            except Exception as exc:
                # If cache access fails, propagate an informative error
                raise RuntimeError(f"Cache access failed: {exc}") from exc
            finally:
                if lock:
                    lock.release()

            # If not cached, compute the result
            try:
                result = func(self, *args, **kwargs)
            except Exception as exc:
                raise RuntimeError(f"Wrapped function raised an exception: {exc}") from exc

            # Store the result in the cache
            try:
                if lock:
                    lock.acquire()
                cache[cache_key] = result
            except Exception as exc:
                raise RuntimeError(f"Cache write failed: {exc}") from exc
            finally:
                if lock:
                    lock.release()

            return result

        return wrapper
