def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    # Determine the output container; default to a list
    try:
        if output is None:
            output_func = list
        else:
            output_func = output
    except Exception:
        output_func = list

    # Empty input yields an empty container
    if sequence is None:
        return output_func()

    # If the sequence itself is not an iterable of the desired kind,
    # treat it as a single element
    if not isinstance(sequence, (list, tuple)):
        return output_func([sequence])

    result = []
    for element in sequence:
        # Expand nested tuples/lists but keep other elements as is
        if isinstance(element, (list, tuple)):
            result.extend(element)
        else:
            result.append(element)
    return output_func(result)

