def reset(self):
    """
    Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value* or with *make_bins()*
    (depending on the initialization).
    """
    # Reset context
    try:
        self.context = {}
    except Exception:
        # If the instance doesn't have a 'context' attribute, ignore.
        pass

    # Reinitialize bins
    if hasattr(self, 'initial_value') and self.initial_value is not None:
        # Preserve existing bin keys if possible
        try:
            keys = list(getattr(self, 'bins', {}).keys())
        except Exception:
            keys = []
        self.bins = {k: self.initial_value for k in keys}
    elif hasattr(self, 'make_bins') and callable(self.make_bins):
        try:
            self.bins = self.make_bins()
        except Exception as exc:
            # Fall back to an empty dict and raise a clear error
            self.bins = {}
            raise RuntimeError(
                f"Failed to reset bins using make_bins(): {exc}"
            ) from exc
    else:
        # If neither initial_value nor make_bins is available, clear bins
        self.bins = {}

