def integral(bins, edges):
    """
    Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert inputs to plain iterables
    try:
        bins_list = list(bins)
        edges_list = list(edges)
    except Exception as exc:
        raise ValueError("bins and edges must be iterable") from exc

    # Basic shape checks
    if len(edges_list) < 2:
        raise ValueError("edges must contain at least two values")
    if len(bins_list) != len(edges_list) - 1:
        raise ValueError("len(bins) must be len(edges) - 1")

    # Convert to floats and validate
    try:
        edges_float = [float(x) for x in edges_list]
    except Exception as exc:
        raise ValueError("edges must contain numeric values") from exc

    # Ensure edges are non‑decreasing
    if any(edges_float[i] > edges_float[i + 1] for i in range(len(edges_float) - 1)):
        raise ValueError("edges must be non‑decreasing (each edge <= next)")

    try:
        bins_float = [float(x) for x in bins_list]
    except Exception as exc:
        raise ValueError("bins must contain numeric values") from exc

    # Compute the integral: sum(bin_value * bin_width)
    total = 0.0
    for width, value in zip(
        [edges_float[i + 1] - edges_float[i] for i in range(len(edges_float) - 1)],
        bins_float,
    ):
        # Warn against negative bin widths (should not happen with previous checks)
        if width < 0:
            raise ValueError("negative bin width encountered")
        total += width * value

    return float(total)

