def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("difference expects dictionaries for d1 and d2")
    # ``level`` must be an integer; allow negative for unlimited recursion
    if isinstance(level, int):
        pass
    else:
        try:
            level = int(level)
        except Exception:
            raise TypeError("level must be an integer or convertible to int")

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # key absent in d2 -> include it
            result[key] = val1
            continue

        val2 = d2[key]
        if val1 == val2:
            # same value - no difference
            continue

        # Values differ
        if isinstance(val1, dict) and isinstance(val2, dict):
            # Determine recursion limit
            if level == 0:
                # no recursion allowed, treat as scalar difference
                result[key] = val1
            else:
                next_level = level - 1 if level > 0 else level
                subdiff = difference(val1, val2, next_level)
                if subdiff:
                    result[key] = subdiff
                # If subdiff is empty, no difference to report
        else:
            # Non-dict values differ
            result[key] = val1

    return result

