def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Basic input validation
    if not isinstance(coord, (list, tuple)):
        raise TypeError("coord must be a list or tuple of coordinates")

    # The histogram must have been initialized with edges and data
    try:
        edges = self._edges      # list of lists/tuples of edges per dimension
        data = self._data        # N-D array or nested lists of counts
    except AttributeError as exc:
        raise AttributeError("The histogram object must have `_edges` and `_data` attributes") from exc

    if not isinstance(edges, (list, tuple)):
        raise TypeError("_edges must be a list or tuple of edge lists")

    if len(coord) != len(edges):
        raise ValueError("Coordinate dimensionality does not match histogram dimensionality")

    # Determine bin indices for each dimension
    indices = []
    for dim, (x, edge_list) in enumerate(zip(coord, edges)):
        if not isinstance(edge_list, (list, tuple)):
            raise TypeError(f"Edge list for dimension {dim} must be a list or tuple")

        # Check bounds: ignore coordinate if outside min/max edge
        if x < edge_list[0] or x >= edge_list[-1]:
            return  # ignore

        # Find bin index: edge[i] <= x < edge[i+1]
        bin_idx = None
        for i in range(len(edge_list) - 1):
            if edge_list[i] <= x < edge_list[i + 1]:
                bin_idx = i
                break

        if bin_idx is None:
            return  # coordinate falls exactly on the upper edge (outside last bin)

        indices.append(bin_idx)

    # Increment the appropriate count
    try:
        tuple_index = tuple(indices)
        # Use nested indexing if data is nested lists
        sub = data
        for idx in indices[:-1]:
            sub = sub[idx]
        sub[indices[-1]] += weight
    except (IndexError, TypeError) as exc:
        # This should not happen if indices are correct
        raise RuntimeError(f"Failed to fill histogram at {coord} with weight {weight}") from exc
    except Exception as exc:
        # Catch any unforeseen errors
        raise RuntimeError(f"An unexpected error occurred while filling the histogram: {exc}") from exc

    return None  # explicit for clarity.

