        if not isinstance(key, (str, bytes)):
            add_error(key, 'expected string or bytes-like object')
        else:
            # Validate key format
            if not _LABEL_KEY_REGEX.match(key):
                add_error(key, f"Label key '{key}' does not match the regex [...]")

        # Validate value
        # If value is an iterable other than string/bytes, treat each element separately
        if isinstance(value, (list, tuple)):
            for item in value:
