        # Allowed characters: alphanumerics, underscore, hyphen
        allowed_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"
        if any(ch not in allowed_chars for ch in key):
