def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from Kubernetes resource kind to its generated default
        observer schema. The mapping is also merged into ``app.spec.observer_schema``
        if that attribute exists; otherwise the mapping is just returned.
    """
    try:
        # Basic validation of the expected structure
        if not hasattr(app, "spec"):
            return {}
        spec = app.spec
        # ``manifest`` should be a list (or a dict) of Kubernetes resource dicts
        if not hasattr(spec, "manifest"):
            return {}
        manifest = spec.manifest
        if isinstance(manifest, dict):
            # Treat a mapping of resource names to objects as a list of values
            resources = list(manifest.values())
        elif isinstance(manifest, list):
            resources = manifest
        else:
            return {}

        # Prepare where custom schemas are stored (if any)
        custom_schemas = getattr(spec, "observer_schema", {})
        if not isinstance(custom_schemas, dict):
            custom_schemas = {}

        generated = {}
        for resource in resources:
            if not isinstance(resource, dict):
                continue
            kind = resource.get("kind")
            if not kind:
                continue
            # Skip kinds that already have a custom schema
            if kind in custom_schemas:
                continue

            # Construct a very simple default schema that references the resource’s
            # name and namespace using the convention used by Krake for
            # "observables". These are placeholders that are later replaced.
            schema = {
                "apiVersion": resource.get("apiVersion", ""),
                "kind": kind,
                "metadata": {
                    "name": "${metadata.name}",
                    "namespace": "${metadata.namespace}",
                },
            }

            generated[kind] = schema

        # Merge the newly generated schemas with any existing ones
        merged = {**custom_schemas, **generated}
        # Store the merged mapping back on the spec if the attribute exists,
        # otherwise simply return the generated mapping.
        if hasattr(spec, "observer_schema"):
            spec.observer_schema = merged
        return merged

    except Exception:
        # In case of any failure, return an empty mapping rather than raising.
        return {}

