def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        os = __import__("os")
        # Resolve path to a string
        if hasattr(path, "__fspath__"):
            path_str = os.fspath(path)
        else:
            path_str = str(path)
        if not os.path.exists(path_str):
            return False
        if not os.path.isdir(path_str):
            return False
        # Basic OCFL structure: expect either an `ocfl-info.json` file
        # or a `.ocfl` directory at the root of the object.
        if not (
            os.path.exists(os.path.join(path_str, "ocfl-info.json"))
            or os.path.exists(os.path.join(path_str, ".ocfl"))
        ):
            return False
        return True
    except Exception:
        return False

