    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise ValueError(f'Inventory must be a dict, got {type(inventory).__name__}')

    # Optional extraction of spec_version based on the 'type' field
    if extract_spec_version:
        type_value = inventory.get('type')
        # A sample mapping of type values to spec versions
        type_to_version = {
            'V1': '1.0',
            'V2': '2.0',
            'V3': '3.0',
        }
        if isinstance(type_value, str):
            self.spec_version = type_to_version.get(type_value, self.spec_version)

    # Ensure required keys exist
    required_keys = {'name', 'id', 'type'}
    missing_keys = required_keys - inventory.keys()
    if missing_keys:
