    supported_versions = {'1.0', '2.0', '3.0'}
    if self.spec_version not in supported_versions:
        raise ValueError(f'Unsupported spec_version: {self.spec_version}')

    # Additional generic sanity checks can be added here (e.g., value types, ranges, etc.)
    return True

