def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate input types
    if manifest_files is None or digests_used is None:
        raise ValueError("Both manifest_files and digests_used must be provided")
    if not isinstance(manifest_files, dict):
        # Attempt to interpret as a list of (filename, digest) tuples
        if isinstance(manifest_files, (list, tuple)):
            try:
                manifest_files = dict(manifest_files)
            except Exception as e:
                raise TypeError("manifest_files must be a dict or a list/tuple of pair values") from e
        else:
            raise TypeError("manifest_files must be a dictionary mapping filenames to digests")
    if not isinstance(digests_used, (set, list, tuple)):
        raise TypeError("digests_used must be a collection (set/list/tuple) of digests")

    # Ensure manifest has digest values
    try:
        manifest_digests = set(manifest_files.values())
    except Exception:
        raise ValueError("manifest_files must map to digest values")

    # Determine missing digests
    digests_needed_set = set(digests_used)
    missing = digests_needed_set - manifest_digests
    if missing:
        raise ValueError(f"Missing digests in manifest: {missing}")

    # Since all required digests are present, we also confirm none are unused
    unused = manifest_digests - digests_needed_set
    if unused:
        # Log or warn: unused digests are present but not needed
        # For now we ignore, but you could optionally raise
        pass

    # If no issue, return True for success
    return True

