def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    result = {}

    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            all_files = [f for f in zf.namelist() if not f.endswith("/")]
            # Map each XML file to its directory and base name
            xml_entries = []
            for fn in all_files:
                if fn.lower().endswith(".xml"):
                    dir_path = os.path.dirname(fn)
                    base = os.path.splitext(os.path.basename(fn))[0]
                    xml_entries.append((fn, dir_path, base))

            for _, dir_path, base in xml_entries:
                # Gather all files that share the same directory
                files_in_dir = [f for f in all_files if os.path.dirname(f) == dir_path]
                data_dict = {}
                for f in files_in_dir:
                    try:
                        raw = zf.read(f)
                        try:
                            content = raw.decode("utf-8", errors="replace")
                        except Exception:
                            content = raw  # fallback to bytes if decoding fails
                        data_dict[f] = content
                    except Exception:
                        data_dict[f] = None
                result[base] = data_dict

    except FileNotFoundError as e:
        raise
    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid zip file: {zip_path}") from e
    except Exception:
        # In case of unexpected errors, return whatever has been gathered so far
        pass

    return result

