def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths.
    O parâmetro `node` deve suportar o método `xpath`.
    Se nenhum caminho encontrar um resultado, retorna `None`.
    """
    if not pubdate_xpaths:
        return None

    for path in pubdate_xpaths:
        try:
            result = node.xpath(path)
            if result:
                # Se o resultado for um elemento XML, devolvemos seu texto
                first = result[0]
                if hasattr(first, 'text'):
                    return first.text
                else:
                    # Pode ser um string já retornado pelo XPath
                    return first
        except Exception:
            # Ignora exceções vindas de XPath inválido ou falha de execução
            continue
    return None

