def pretty(self, indent: int = 0, debug: bool = False):
        """
        Return a pretty formatted representation of `self`.

        Parameters
        ----------
        indent : int, optional
            The starting indentation level (used to control the base width of the
            output). Defaults to 0.
        debug : bool, optional
            If True, include the class name and memory address for custom objects.
            Defaults to False.

        Returns
        -------
        str
            A human‑readable string representation of the object.
        """
        visited = set()

        def _format(obj, level):
            # Prevent infinite recursion on self‑referencing structures.
            if id(obj) in visited and not isinstance(obj, str):
                return '...'
            visited.add(id(obj))

            # Basic built‑in types
            if obj is None or isinstance(obj, (bool, int, float)):
                return repr(obj)
            if isinstance(obj, str):
                return repr(obj)

            # Sequence types
            if isinstance(obj, (list, tuple, set)):
                if not obj:
                    return type(obj).__name__ + '()'
                inner = []
                for item in obj:
                    inner.append(_format(item, level + 1))
                sep = ',\n' + '  ' * (level + 1)
                if isinstance(obj, list):
                    return f'[{sep}'.join([''] + inner + ['']) + f'\n{"  " * level}]'
                if isinstance(obj, tuple):
                    return f'({sep}'.join([''] + inner + ['']) + f'\n{"  " * level})'
                if isinstance(obj, set):
                    return f'{{{sep}'.join([''] + inner + ['']) + f'\n{"  " * level}}}'

            # Mapping types
            if isinstance(obj, dict):
                if not obj:
                    return '{}'
                inner = []
                for k, v in obj.items():
                    inner.append(f'{repr(k)}: {_format(v, level + 1)}')
                sep = ',\n' + '  ' * (level + 1)
                return f'{{{sep}'.join([''] + inner + ['']) + f'\n{"  " * level}}}'

            # Custom objects: try __dict__ or __slots__
            if hasattr(obj, '__dict__'):
                attrs = obj.__dict__
                inner = []
                for k, v in attrs.items():
                    inner.append(f'{repr(k)}: {_format(v, level + 1)}')
                sep = ',\n' + '  ' * (level + 1)
                repr_str = f'{obj.__class__.__name__}({{"{sep}".join([""] + inner + [""])}})\n{"  " * level})'
                if debug:
                    repr_str += f'  # id={id(obj)}'
                return repr_str

            # Fallback for any other object
            try:
                return repr(obj)
            except Exception:
                return str(obj)

        return _format(self, indent)

