def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Use importlib.metadata for Python ≥ 3.8; fallback to backport
        try:
            from importlib import metadata as importlib_metadata
        except Exception:
            import importlib_metadata
        # Determine the top-level package name
        package = __name__.split('.')[0]
        if package:
            version = importlib_metadata.version(package)
            return {"version": version, "full-revisionid": None, "dirty": False}
    except Exception:
        # Suppress any exception and fall back to a default value
        pass
    return {"version": "0+unknown", "full-revisionid": None, "dirty": False}

