def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess, os, shlex, sys
    # Ensure args is a list
    if args is None:
        args = []
    if not isinstance(args, list):
        raise ValueError("args must be a list of arguments")
    # Prepare the command
    use_shell = False
    if isinstance(commands, list):
        cmd = commands + args
    elif isinstance(commands, str):
        # Quote arguments for shell usage
        quoted = " ".join(shlex.quote(arg) for arg in args)
        cmd = commands + (" " + quoted if quoted else "")
        use_shell = True
    else:
        raise ValueError("commands must be a list or string")
    # Prepare environment
    if env is not None:
        if not isinstance(env, dict):
            raise ValueError("env must be a mapping or None")
        env_dict = {**os.environ, **env}
    else:
        env_dict = None
    # Verbose output
    if verbose:
        print(f"Running command: {cmd}")
    # Execute
    try:
        result = subprocess.run(
            cmd,
            shell=use_shell,
            cwd=cwd,
            env=env_dict,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=False,
            text=True
        )
    except OSError as e:
        raise RuntimeError(f"Failed to execute command: {e}") from e
    # Handle output
    stdout = result.stdout
    stderr = result.stderr
    if result.returncode != 0:
        if not hide_stderr and stderr:
            print(stderr, file=sys.stderr)
        raise subprocess.CalledProcessError(
            returncode=result.returncode,
            cmd=cmd,
            output=stdout,
            stderr=stderr
        )
    if not hide_stderr and stderr:
        # In case of non-error but there is stderr output
        print(stderr, file=sys.stderr)
    return stdout

