    # Validate that the root path is set and is a string
    root_path = getattr(self, "root_path", None)
    if not isinstance(root_path, str) or not root_path:
        raise ValueError("`root_path` must be a non-empty string representing the storage root directory.")

    # Ensure the root directory exists
    try:
