def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        os = __import__('os')
        re = __import__('re')
    except Exception as e:
        return f"Import error: {e}"
    if path is None:
        return "No path provided"
    if not isinstance(path, str):
        return "Invalid path type (expected string)"
    try:
        if not os.path.exists(path):
            return "Path does not exist"
        if os.path.isfile(path):
            return 'file'
        if os.path.isdir(path):
            try:
                items = os.listdir(path)
            except Exception as e:
                return f"Cannot list directory: {e}"
            namaste_files = [f for f in items if re.match(r'^0=.*', f)]
            if not namaste_files:
                return "No Namaste file found"
            # Heuristic to differentiate root vs object:
            # If the directory contains a 'manifest' or 'index' file we treat it as root.
            # Otherwise treat it as an object directory.
            lower_items = [i.lower() for i in items]
            if ('manifest' in lower_items) or ('index' in lower_items) or any(f.startswith('audit.log') for f in items):
                return 'root'
            else:
                return 'object'
    except Exception as e:
        return f"Error processing path: {e}"
    return "Unknown type"

