def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Validate the params argument
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")

    # If no bug IDs were provided, just return the params unchanged
    if not bug_ids:
        return params

    # Build a list of integer bug IDs, validating each entry
    bug_id_list = []
    for b in bug_ids:
        try:
            # Accept ints directly
            if isinstance(b, int):
                bug_id_list.append(b)
            # Accept numeric strings that represent integers
            elif isinstance(b, str) and b.isdigit():
                bug_id_list.append(int(b))
            else:
                raise ValueError(f"Invalid bug id: {b!r}")
        except Exception as exc:
            # Catch any unexpected type issues
            raise ValueError(f"Invalid bug id: {b!r}") from exc

    # If we have valid bug IDs, add them to the parameters
    if bug_id_list:
        # Use a sorted, unique list for consistency
        unique_ids = sorted(set(bug_id_list))
        # Bugzilla expects a comma-separated string for the 'ids' key
        params["ids"] = ",".join(map(str, unique_ids))

    return params

