def deep_merge_nodes(nodes):
    '''
    Merge duplicate keys in a list of (ScalarNode, value) tuples, deep merging
    MappingNode values. For non-MappingNode conflicts, the later value wins.
    '''
    from ruamel.yaml.nodes import MappingNode

    def merge_lists(left, right):
        """Merge two MappingNode value lists (list of tuples)."""
        merged = []
        # dictionary to group by key value
        key_map = {}
        for k, v in left:
            key_map[k.value] = (k, v)
        for k, v in right:
            key_val = k.value
            if key_val in key_map:
                _, existing_v = key_map[key_val]
                # both are MappingNode? deep merge
                if isinstance(existing_v, MappingNode) and isinstance(v, MappingNode):
                    merged_value = merge_lists(existing_v.value, v.value)
                    new_node = MappingNode(tag=existing_v.tag, value=merged_value)
                    key_map[key_val] = (k, new_node)
                else:
                    # last wins
                    key_map[key_val] = (k, v)
            else:
                key_map[key_val] = (k, v)
        # preserve order of first appearance
        for _, (k, v) in key_map.items():
            merged.append((k, v))
        return merged

    result_map = {}
    order = []

    for key, value in nodes:
        if not hasattr(key, 'value'):
            # skip invalid key
            continue
        key_val = key.value
        if key_val in result_map:
            existing_key, existing_value = result_map[key_val]
            if isinstance(existing_value, MappingNode) and isinstance(value, MappingNode):
                merged_value = merge_lists(existing_value.value, value.value)
                new_node = MappingNode(tag=existing_value.tag, value=merged_value)
                # keep the original key node
                result_map[key_val] = (existing_key, new_node)
            else:
                # last wins
                result_map[key_val] = (key, value)
        else:
            result_map[key_val] = (key, value)
            order.append(key_val)

    # Construct final list preserving order
    merged_nodes = []
    for key_val in order:
        key_node, value_node = result_map[key_val]
        merged_nodes.append((key_node, value_node))

    return merged_nodes

