    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse

    # the caller may pass a single iterable or multiple positional args
    if len(unparsed_arguments) == 1 and hasattr(unparsed_arguments[0], '__iter__') and not isinstance(unparsed_arguments[0], (str, bytes)):
        args = list(unparsed_arguments[0])
    else:
        args = list(unparsed_arguments)

    parser = argparse.ArgumentParser(add_help=False)
    # try to discover subparsers that might have been added elsewhere
    subparsers = None
    if hasattr(parser, 'add_subparsers'):
        subparsers = parser.add_subparsers(dest='subcommand')
    try:
        # first parse global options
        ns_global, remaining = parser.parse_known_args(args)

        result = {'global': ns_global}

        # if there is a subparser defined, try to parse the rest for it
        if subparsers is not None and hasattr(ns_global, 'subcommand') and ns_global.subcommand is not None:
            # hard‑to‑guess: many scripts add subparsers via parents but we still have no specific subparser
