def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if not hasattr(dicts, "__iter__"):
        raise TypeError("dicts must be an iterable")
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError("elements of dicts must be dictionaries")
        for key, val in d.items():
            if key in result:
                try:
                    result[key] += val
                except TypeError:
                    raise TypeError(f"Cannot sum values for key {key}") from None
            else:
                result[key] = val
    return result

