def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class type, got {type(cls).__name__!r}")
    result = set()
    def _collect(current):
        try:
            sub = current.__subclasses__()
        except TypeError:  # Shouldn't happen but guard
            return
        for subcls in sub:
            if subcls not in result:
                result.add(subcls)
                _collect(subcls)
    _collect(cls)
    return list(result)

