def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number using the provided alphabet.
    The most significant digit is first in the string.
    """
    # Validate inputs
    if not isinstance(string, str):
        raise TypeError(f"Expected string for 'string', got {type(string).__name__}")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"Expected list for 'alphabet', got {type(alphabet).__name__}")
    if len(alphabet) == 0:
        raise ValueError("Alphabet must contain at least one character")

    # Build mapping from character to its numeric value
    mapping = {}
    for idx, ch in enumerate(alphabet):
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError(f"Alphabet entries must be single characters, got {ch!r}")
        if ch in mapping:
            raise ValueError(f"Duplicate character '{ch}' found in alphabet")
        mapping[ch] = idx

    base = len(alphabet)
    value = 0
    for ch in string:
        if ch not in mapping:
            raise ValueError(f"Character '{ch}' not found in alphabet")
        value = value * base + mapping[ch]

    return value

