def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    import shlex

    if s is None:
        return []

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        try:
            return shlex.split(s, posix=True)
        except ValueError as e:
            raise ValueError(f"POSIX parsing error: {e}") from None
    elif platform == 0:  # Windows
        try:
            return shlex.split(s, posix=False)
        except ValueError as e:
            raise ValueError(f"Windows parsing error: {e}") from None
    else:
        raise ValueError(f"Unsupported platform specifier: {platform}")

