def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str):
        return False
    host = host.strip()
    if not host:
        return False

    # Direct string checks for common localhost representations
    if host.lower() == "localhost":
        return True

    # Helper to check IPv4 loopback
    def is_ipv4_loopback(ip_str):
        try:
            # socket.inet_aton raises if not a valid IPv4 literal
            packed = socket.inet_aton(ip_str)
            return packed == b'\x7f\x00\x00\x01'  # 127.0.0.1
        except (OSError, TypeError, AttributeError):
            return False

    # Helper to check IPv6 loopback
    def is_ipv6_loopback(ip_str):
        try:
            if hasattr(socket, "inet_pton"):
                packed = socket.inet_pton(socket.AF_INET6, ip_str)
                return packed == b'\x00' * 15 + b'\x01'  # ::1
        except (OSError, TypeError, AttributeError):
            return False
        return False

    # First try literal IP checks
    if is_ipv4_loopback(host) or is_ipv6_loopback(host):
        return True

    # Resolve hostnames to addresses and check each
    try:
        infos = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
    except socket.gaierror:
        return False
    except Exception:
        return False

    for family, _, _, _, sockaddr in infos:
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if is_ipv4_loopback(ip):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            if is_ipv6_loopback(ip):
                return True
    return False

