def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # only Windows has os.name == 'nt', git-bash sets OSTYPE to 'msys' or 'cygwin'
        if os.name != 'nt':
            return False
        ostype = os.getenv('OSTYPE', '').lower()
        return ostype.startswith('msys') or ostype.startswith('cygwin')
    except Exception:
        # in any unexpected situation, conservatively return False
        return False

