def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate input types
    if not isinstance(config_filename, str):
        raise TypeError(f"config_filename must be a string, got {type(config_filename).__name__}")
    if not isinstance(rendered_config, str):
        raise TypeError(f"rendered_config must be a string, got {type(rendered_config).__name__}")
    if not isinstance(mode, int):
        raise TypeError(f"mode must be an int, got {type(mode).__name__}")
    if not isinstance(overwrite, bool):
        raise TypeError(f"overwrite must be a bool, got {type(overwrite).__name__}")

    # Resolve absolute path to handle relative directories and defensive coding
    abs_path = os.path.abspath(config_filename)
    dir_path = os.path.dirname(abs_path)

    # Create parent directories if they do not exist
    if dir_path:
        try:
            os.makedirs(dir_path, exist_ok=True)
        except Exception as exc:
            raise OSError(f"Failed to create directories '{dir_path}': {exc}") from exc

    # Check existence and overwrite policy
    if os.path.exists(abs_path):
        if not overwrite:
            raise FileExistsError(f"File '{abs_path}' already exists and overwrite is set to False.")
        # If overwrite is True, we will overwrite the existing file

    # Write the configuration data
    try:
        with open(abs_path, 'w', encoding='utf-8') as f:
            f.write(rendered_config)
    except Exception as exc:
        raise OSError(f"Could not write to file '{abs_path}': {exc}") from exc

    # Set the file mode/permissions
    try:
        os.chmod(abs_path, mode)
    except Exception as exc:
        raise OSError(f"Could not set mode '{oct(mode)}' on file '{abs_path}': {exc}") from exc
    return None

