def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        if values is None:
            raise ValueError("values cannot be None")
        try:
            raw_list = list(values)
        except TypeError as exc:
            raise TypeError("values must be an iterable of strings") from exc

        for idx, v in enumerate(raw_list):
            if not isinstance(v, str):
                raise TypeError(f"Element {idx} must be a string, got {type(v).__name__}")
            # Validate ASCII
            try:
                v.encode('ascii')
            except UnicodeEncodeError as exc:
                raise ValueError(f"Bookmark at index {idx} contains non-ASCII characters: {v}") from exc

        # Create an instance of the Bookmarks class
        obj = cls()
        # Store the raw bookmarks in an attribute commonly used by the class.
        # If the class defines a `values` attribute, use it; otherwise,
        # fall back to a generic `bookmarks` attribute.
        if hasattr(obj, "values"):
            obj.values = raw_list
        else:
            setattr(obj, "bookmarks", raw_list)
        return obj

