def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Helper to check for sliceable sequence
    def is_sliceable(x):
        return hasattr(x, "__len__") and hasattr(x, "__getitem__")

    try:
        if is_sliceable(seq):
            # seq is already a sliceable sequence (list, tuple, str, bytes, bytearray, range, etc.)
            if bufsize is not None:
                # use slicing if possible; slice will raise TypeError on unsupported types
                try:
                    derived = seq[:bufsize]
                except Exception:
                    derived = list(seq)[:bufsize] if bufsize is not None else list(seq)
            else:
                derived = seq
        elif hasattr(seq, "__iter__"):
            # seq is an iterable but not sliceable (e.g., generator, set, dict)
            if bufsize is not None:
                from itertools import islice
                derived = list(islice(seq, bufsize))
            else:
                derived = list(seq)
        else:
            # seq is a scalar; wrap it in a list
            derived = [seq]
    except Exception:
        # Fallback: treat as single element list
        derived = [seq]
    return derived, type(derived)

