def hist_to_graph(hist, make_value=None, get_coordinate="left",
                   field_names=("x", "y"), scale=None):
    """Convert a histogram to a graph representation.

    The function accepts either a histogram object with attributes
    ``edges`` and ``contents`` (and optionally ``scale``) or a tuple
    ``(edges, contents)``.  The returned graph is a dictionary with
    keys: ``points`` (a list of tuples) and optional ``scale``.
    """
    # Resolve histogram structure
    try:
        edges = hist.edges
        contents = hist.contents
        hist_scale = getattr(hist, "scale", None)
    except AttributeError:
        # Perhaps hist is a tuple
        try:
            edges, contents = hist
            hist_scale = None
        except Exception:
            raise ValueError("Histogram must have 'edges' and 'contents' attributes "
                             "or be a tuple (edges, contents).")

    if not isinstance(edges, (list, tuple)):
        raise TypeError("Histogram edges must be a list or tuple.")
    if not isinstance(contents, (list, tuple)):
        raise TypeError("Histogram contents must be a list or tuple.")

    n_bins = len(edges) - 1
    if n_bins <= 0:
        raise ValueError("Histogram must contain at least one bin.")

    # Prepare coordinate extraction
    coord_methods = {
        "left": lambda i: edges[i],
        "right": lambda i: edges[i + 1],
        "middle": lambda i: (edges[i] + edges[i + 1]) / 2,
    }
    if get_coordinate not in coord_methods:
        raise ValueError(f"Unsupported get_coordinate: {get_coordinate!r}")
    get_coord = coord_methods[get_coordinate]

    # Default make_value
    if make_value is None:
        def make_value(x):  # noqa: ANN001
            return x

    # Validate field_names
    if not isinstance(field_names, (list, tuple)):
        raise TypeError("field_names must be a list or tuple.")
    if len(field_names) < 1:
        raise ValueError("field_names must contain at least one entry.")

    points = []
    for i in range(n_bins):
        try:
            bin_val = contents[i]
        except Exception as exc:
            raise ValueError(f"Cannot access content of bin {i}") from exc

        try:
            val = make_value(bin_val)
        except Exception as exc:
            raise ValueError(f"make_value failed for bin {i}") from exc

        # Ensure val is iterable (except string or bytes)
        if isinstance(val, (list, tuple)):
            val_tuple = tuple(val)
        else:
            val_tuple = (val,)

        # Prefix coordinate
        point = (get_coord(i),) + val_tuple

        # Check number of fields matches field_names
        if len(point) != len(field_names):
            raise ValueError(f"Number of values {len(point)} does not match "
                             f"field_names length {len(field_names)} for bin {i}")

        points.append(point)

    # Construct graph
    graph = {"points": points}
    # Handle scale
    if scale is True:
        graph["scale"] = hist_scale
    elif scale is not None:
        graph["scale"] = scale

    return graph

