def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    If *tentative* is False, a TypeError is raised when the check fails,
    otherwise the function simply returns False.
    The function returns True when the check passes.
    """
    # Resolve the interface specification if given as a string.
    if isinstance(iface, str):
        try:
            module_name, class_name = iface.rsplit(".", 1)
            importlib = __import__("importlib")
            module = importlib.import_module(module_name)
            iface_cls = getattr(module, class_name)
        except Exception as exc:
            raise ValueError(f"Cannot resolve interface from string {iface!r}") from exc
    elif isinstance(iface, type):
        iface_cls = iface
    else:
        raise TypeError(f"Interface must be a type or fully‑qualified class name string, got {type(iface).__name__}")

