    if isinstance(candidate, type):
        candidate_cls = candidate
    elif hasattr(candidate, "__class__"):
        candidate_cls = type(candidate)
    else:
        raise TypeError(f"Candidate {candidate!r} is not a class or class instance")

    # First, try a normal subclass check.
    try:
        if issubclass(candidate_cls, iface_cls):
            return True
    except TypeError:
        # issubclass fails if either arg is not a class.
