    # Fallback: duck type checking.
    required_attrs = [attr for attr in dir(iface_cls) if not attr.startswith("_")]
    if all(hasattr(candidate_cls, attr) for attr in required_attrs):
        return True

    if tentative:
        return False
    raise TypeError(f"{candidate_cls.__name__!r} does not provide {iface_cls.__name__!r}")

