def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Attempt to retrieve the least frequently used frequency and its items map.
    try:
        min_freq = self.min_freq  # frequency with the least usage
        freq_map = self.freq_map[min_freq]
    except Exception:
        # If any expected attribute is missing or the structure is empty,
        # raise KeyError similar to standard dict.popitem().
        raise KeyError("popitem(): dictionary is empty")

    # Remove a key/value pair from the freq_map.
    # freq_map might be an OrderedDict; favor removing the first inserted item.
    try:
        if hasattr(freq_map, "popitem"):
            # Try to pop the first item if possible.
            try:
                key, value = freq_map.popitem(last=False)  # py3.7+
            except TypeError:
                # popitem() without argument pops from the right (most recent).
                key, value = next(iter(freq_map.items()))
                del freq_map[key]
        else:
            # Fallback: use list conversion if freq_map is a plain dict.
            iterator = iter(freq_map.items())
            key, value = next(iterator)
            del freq_map[key]
    except Exception as e:
        # If we cannot pop any item, the structure is considered empty.
        raise KeyError("popitem(): dictionary is empty") from e

    # Clean up auxiliary maps.
    try:
        del self.key_to_val[key]
        del self.key_to_freq[key]
    except Exception:
        # The key might have been missing from these maps; ignore.
        pass

    # If the freq_map for this frequency is now empty, remove it and update min_freq.
    if not freq_map:
        try:
            del self.freq_map[min_freq]
        except Exception:
            pass
        # Set min_freq to the next minimal frequency or zero if none remain.
        if self.freq_map:
            # Choose the smallest key in freq_map which represents the next min freq.
            try:
                self.min_freq = min(self.freq_map)
            except Exception:
                self.min_freq = 0
        else:
            self.min_freq = 0

    return key, value

