def default_tzinfo(dt, tzinfo):
    """
    Sets the ``tzinfo`` parameter on naive datetimes only
    """
    # Validate input type for ``dt`` – it must have a ``tzinfo`` attribute
    try:
        current_tz = dt.tzinfo
    except AttributeError:
        raise TypeError("dt must be a datetime.datetime instance")

    if tzinfo is None:
        raise ValueError("tzinfo must be provided")

    # If ``dt`` is naive (no tzinfo), assign the supplied tzinfo
    if current_tz is None:
        try:
            return dt.replace(tzinfo=tzinfo)
        except Exception as exc:
            # Propagate a clear error if replace failed
            raise ValueError(f"Failed to set tzinfo: {exc}") from exc
    # Otherwise return the original datetime unchanged
    return dt

