def xml_children_as_dict(node):
    """
    Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # Graceful handling for None or non-iterable nodes
    if node is None:
        return {}
    try:
        children = list(node)
    except Exception:
        # If node is not iterable, return empty dict
        return {}
    result = {}
    for child in children:
        tag = getattr(child, 'tag', None)
        if tag is None:
            # Skip elements without a tag attribute
            continue
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

