def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Attempt to parse as JSON using a safe eval.
        safe_globals = {"__builtins__": None, "True": True, "False": False, "None": None}
        parsed = eval(document, safe_globals, {})
        if isinstance(parsed, dict):
            return parsed
    except Exception:
        pass  # fall back to XRD parsing

    try:
        re = __import__("re")
    except Exception:
        # If regex import fails, return empty dict.
        return {}

    result: dict = {}
    # Extract subject
    subject_match = re.findall(r"<Subject>(.*?)</Subject>", document, re.S)
    if subject_match:
        result["subject"] = subject_match[0].strip()

    # Extract all Link tags (self-closing or normal).
    link_tag_pattern = r"<Link\s+([^/>]+?)\s*/?>"
    link_tags = re.findall(link_tag_pattern, document, re.S)
    links = []
    for attrs_str in link_tags:
        attrs: dict = {}
        # Find all key="value" pairs
        for key, value in re.findall(r'(\w+)\s*=\s*"([^"]*)"', attrs_str):
            attrs[key] = value
        if attrs:
            links.append(attrs)
    if links:
        result["links"] = links

    return result

