def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file names from the given settings directories
    filtered by the spec_option pattern(s). If a directory does not
    exist, it is silently skipped. The returned paths are absolute.
    """
    # Ensure settings_dirs is a list
    if isinstance(settings_dirs, str):
        # Split on common separators
        dirs = [d.strip() for d in settings_dirs.replace(';', ',').split(',') if d.strip()]
    else:
        dirs = list(settings_dirs)

    # Prepare patterns for matching
    if spec_option is None:
        patterns = [None]
    elif isinstance(spec_option, str):
        patterns = [spec_option]
    elif isinstance(spec_option, (list, tuple, set)):
        patterns = [p for p in spec_option if isinstance(p, str)]
        if not patterns:
            patterns = [None]
    else:
        # Unsupported type, skip filtering
        patterns = [None]

    result = []
    try:
        import os
        import fnmatch
    except Exception:
        return result

    for dir_path in dirs:
        try:
            if not os.path.isdir(dir_path):
                continue
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if not os.path.isfile(full_path):
                    continue
                if None in patterns:
                    result.append(full_path)
                else:
                    matched = False
                    for pat in patterns:
                        if fnmatch.fnmatch(entry, pat):
                            matched = True
                            break
                    if matched:
                        result.append(full_path)
        except (OSError, PermissionError):
            # Skip directories/files that cannot be accessed
            continue

    result.sort()
    return result

