def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("Spec content cannot be None")

        # Load YAML content if it is a string; otherwise assume it is already a dict
        spec_data = spec_content
        if isinstance(spec_content, str):
            try:
                # Import yaml lazily to avoid a hard dependency
                import yaml
                spec_data = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f"Failed to parse YAML content: {exc}")

        if not isinstance(spec_data, dict):
            raise IRValidatorException("Spec content must be a YAML mapping (dictionary)")

        # Define required fields
        required_fields = {"name", "version", "metadata"}
        missing = required_fields - spec_data.keys()
        if missing:
            raise IRValidatorException(f"Missing required fields in spec: {', '.join(sorted(missing))}")

        return spec_data

