def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Basic type checks
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Determine the set of deprecated arguments.
    # Expect the class to define a set/list `deprecated_args` or `deprecated_parameters`.
    deprecated = set()
    if hasattr(self, "deprecated_args"):
        deprecated.update(self.deprecated_args)
    if hasattr(self, "deprecated_parameters"):
        deprecated.update(self.deprecated_parameters)

    if not deprecated:
        # No deprecated arguments defined; nothing to validate
        return

    import warnings

    # Check CLI arguments
    for key in cli_args:
        if key in deprecated:
            warnings.warn(
                f"Command-line argument '{key}' is deprecated and will be removed in a future release.",
                DeprecationWarning,
                stacklevel=2,
            )
    # Check answer file arguments
    for key in answer_file_args:
        if key in deprecated:
            warnings.warn(
                f"Answer file argument '{key}' is deprecated and will be removed in a future release.",
                DeprecationWarning,
                stacklevel=2,
            )

