def validate_length_args(self, args):
    """
    Check if the value of arguments is not longer than the length specified in
    ``self.max_lengths`` (a mapping of argument name to maximum length).

    :param args: The received arguments (expected to be a mapping from argument
                 names to values).
    :raises ValueError: If any argument exceeds its specified maximum length.
    :raises TypeError: If ``args`` is not a mapping or the values do not support
                       length checking.
    :return: True if all arguments satisfy their length constraints.
    """
    if args is None:
        raise ValueError("No arguments provided to validate.")
    if not isinstance(args, dict):
        raise TypeError(f"Expected args to be a dict, got {type(args).__name__}.")

    # Retrieve the length constraints defined on the instance; default to empty mapping.
    max_lengths = getattr(self, "max_lengths", {}) or {}
    errors = []

    for name, value in args.items():
        # Determine the maximum allowed length for this argument.
        max_len = max_lengths.get(name)
        if max_len is None:
            # No length restriction for this argument.
            continue

        # None values are considered acceptable (no length to check).
        if value is None:
            continue

        try:
            actual_len = len(value)
        except TypeError:
            errors.append(
                f"Argument '{name}' (value: {value!r}) does not support len()"
            )
            continue

        if actual_len > max_len:
            errors.append(
                f"Argument '{name}' length {actual_len} exceeds maximum {max_len}"
            )

    if errors:
        raise ValueError("; ".join(errors))

    return True

