def validate_min_max_args(self, args):
        """
        Check if the value of arguments is between minimum and maximum values.

        The function accepts either a dictionary or a tuple/list containing the
        value and the bounds. Accepted formats:
            1. {'value': <number>, 'min': <number>, 'max': <number>}
            2. {'min': <number>, 'max': <number>, 'value': <number>}
            3. (value, min, max)
            4. [value, min, max]

        Raises:
            ValueError: If the input format is unsupported, types are invalid,
                        or the value is outside the [min, max] range.
        Returns:
            bool: True if the value is within the specified range.
        """
        # Normalise input to a dict with keys 'value', 'min', 'max'
        data = {}
        try:
            if isinstance(args, dict):
                # Dictionary form
                if 'value' in args and 'min' in args and 'max' in args:
                    data['value'] = args['value']
                    data['min'] = args['min']
                    data['max'] = args['max']
                else:
                    raise ValueError("Dictionary must contain 'value', 'min', and 'max' keys.")
            elif isinstance(args, (list, tuple)):
                # Tuple/list form should have exactly 3 elements
                if len(args) != 3:
                    raise ValueError("Tuple/list must contain exactly three elements: (value, min, max).")
                data['value'], data['min'], data['max'] = args
            else:
                raise ValueError("Unsupported argument type; expected dict or tuple/list.")
        except Exception as exc:
            raise ValueError(f"Invalid arguments: {exc}")

        # Convert to comparable numeric types
        try:
            min_val = float(data['min'])
            max_val = float(data['max'])
            val = float(data['value'])
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Non-numeric value encountered: {exc}")

        if min_val > max_val:
            raise ValueError(f"Minimum bound {min_val} is greater than maximum bound {max_val}.")

        if not (min_val <= val <= max_val):
            raise ValueError(f"Value {val} is outside the range [{min_val}, {max_val}].")

        return True

