def get_nested_custom_and_control_args(self, args):
        """
        Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        control_args = {}
        nested_args = {}

        # Helper to parse an individual argument.
        def _parse(arg):
            """
            Parse a single argument string into a (key, value) tuple.
            Supports:
                - "--key=value" or "-key=value" or "key=value"
                - "--flag" or "-flag" or "flag" (value set to True)
            """
            if not isinstance(arg, str):
                raise ValueError(f"Argument must be a string, got {type(arg).__name__}")
            # Remove leading hyphens
            key_part = arg.lstrip('-')
            if '=' in key_part:
                k, v = key_part.split('=', 1)
                return k.strip(), v.strip()
            else:
                return key_part.strip(), True

        # Retrieve known control argument names if defined on the instance;
        # fallback to empty set if not present.
        control_names = getattr(self, "control_args_names", set())
        if control_names and not isinstance(control_names, (set, list)):
            # If attribute exists but is not a set/list, convert to set
            control_names = set(control_names)

        # Defensive: args may be None or not iterable.
        if args is None:
            return {}, {}
        if not isinstance(args, (list, tuple)):
            raise TypeError(f"args must be a list or tuple, got {type(args).__name__}")

        for raw_arg in args:
            try:
                key, value = _parse(raw_arg)
            except Exception as exc:
                # Skip malformed argument, optionally log or raise
                # Here we simply ignore and continue
                continue

            if key in control_names:
                control_args[key] = value
            else:
                nested_args[key] = value

        return control_args, nested_args

