def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level (integer 1-4)
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Basic input validation
    if ir_workspace is None:
        raise ValueError("ir_workspace must be provided")
    if ir_plugin is None:
        raise ValueError("ir_plugin must be provided")
    if not isinstance(playbook_path, (str, bytes)):
        raise ValueError("playbook_path must be a string or bytes")
    if verbose is not None:
        if not isinstance(verbose, int):
            raise ValueError("verbose must be an integer")
        if verbose < 1 or verbose > 4:
            raise ValueError("verbose must be between 1 and 4")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise ValueError("extra_vars must be a dict or None")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise ValueError("ansible_args must be a dict or None")

    cmd = ["ansible-playbook", str(playbook_path)]

    # Add verbosity
    if verbose:
        cmd.append("-" + "v" * verbose)

    # Add ansible_args
    if ansible_args:
        for key, value in ansible_args.items():
            # Convert key to flag format
            flag = "--" + key.replace("_", "-")
            if isinstance(value, bool):
                if value:
                    # include flag only when True
                    cmd.append(flag)
                # skip when False
            else:
                cmd.append(flag)
                if value is not None:
                    cmd.append(str(value))

    # Add extra vars
    if extra_vars:
        try:
            # Convert dict to JSON string safely
            # Using simple str conversion if json is unavailable
            json_repr = str(extra_vars)
        except Exception:
            json_repr = str(extra_vars)
        cmd.extend(["--extra-vars", json_repr])

    try:
        # Execute command using the plugin's run method
        result = ir_plugin.run(cmd)
        return result
    except Exception as exc:
        raise RuntimeError(f"Failed to run ansible-playbook: {exc}") from exc

