def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        def _convert(value):
            # If value is already a basic type (int, float, bool, None), leave it.
            if isinstance(value, (int, float, bool)) or value is None:
                return value

            # Strings are converted.
            if isinstance(value, str):
                s = value.strip()
                # Boolean values
                low = s.lower()
                if low == "true":
                    return True
                if low == "false":
                    return False

                # None values
                if low in ("none", "null"):
                    return None

                # Numeric values
                try:
                    # Allow hex and octal representations
                    if s.startswith(("0x", "0X")):
                        return int(s, 0)
                    if s.startswith(("0o", "0O")):
                        return int(s, 0)
                    if s.isdigit() or (s.startswith("-") and s[1:].isdigit()):
                        return int(s)
                except Exception:
                    pass

                try:
                    return float(s)
                except Exception:
                    pass

                # Comma separated lists
                if "," in s:
                    return [_convert(part.strip()) for part in s.split(",")]

                return s

            # If value is a list or tuple, convert each element.
            if isinstance(value, (list, tuple)):
                new = [_convert(v) for v in value]
                return type(value)(new)

            # If value is a dict, convert recursively.
            if isinstance(value, dict):
                return {k: _convert(v) for k, v in value.items()}

            # Unsupported type, return as is.
            return value

        if not isinstance(values_dict, dict):
            raise TypeError("values_dict must be a dict")

        for key in list(values_dict):
            try:
                values_dict[key] = _convert(values_dict[key])
            except Exception as exc:
                # Log or raise a conversion failure; here we raise to be explicit.
                raise ValueError(
                    f"Failed to convert argument '{key}' with value '{values_dict[key]}': {exc}"
                ) from exc

        return values_dict

