def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Helper to recursively flatten a dictionary
    def _flatten(d, parent_key='', sep='.', result=None):
        if result is None:
            result = {}
        for key, value in d.items():
            full_key = f"{parent_key}{sep}{key}" if parent_key else key
            if isinstance(value, dict):
                _flatten(value, full_key, sep, result)
            else:
                result[full_key] = value
        return result

    # Determine spec file path (support .yaml/.yml/.json)
    spec_path = None
    for name in ('spec.yaml', 'spec.yml', 'spec.json', 'plugin.yaml', 'plugin.yml', 'plugin.json'):
        candidate = os.path.join(plugin_dir, name)
        if os.path.isfile(candidate):
            spec_path = candidate
            break
    if not spec_path:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Try to load the spec file
    try:
        if spec_path.endswith(('.yaml', '.yml')):
            import yaml
            with open(spec_path, 'r', encoding='utf-8') as f:
                raw_spec = yaml.safe_load(f)
